RESOURCE_PATH = re.compile(r"^/resources/(\d+)/(download|read)/$")


def backfill_resource_access(apps, schema_editor):
    """访问记录里早就有下载和阅读的路径，把它们补进下载记录，这样开学以来的数据不丢。

    非 Markdown 资料点「阅读」会跳到下载，下载那一跳另有一条记录，所以这种阅读不算。
    """
    alias = schema_editor.connection.alias
    VisitLog = apps.get_model("board", "VisitLog")
    Resource = apps.get_model("board", "Resource")
    ResourceAccess = apps.get_model("board", "ResourceAccess")
    markdown = {}
    for resource in Resource.objects.using(alias).only("pk", "original_filename", "file"):
        name = resource.original_filename or resource.file.name or ""
        markdown[resource.pk] = PurePath(name).suffix.lower() in {".md", ".markdown"}
    batch = []
    visits = (VisitLog.objects.using(alias).exclude(user=None)
              .filter(path__startswith="/resources/").only("user_id", "path", "created_at").order_by("pk"))
    for visit in visits.iterator():
        match = RESOURCE_PATH.match(visit.path)
        if not match:
            continue
        pk, kind = int(match[1]), match[2]
        if pk not in markdown or (kind == "read" and not markdown[pk]):
            continue
        batch.append(ResourceAccess(user_id=visit.user_id, resource_id=pk, kind=kind, created_at=visit.created_at))
    ResourceAccess.objects.using(alias).bulk_create(batch, batch_size=500)


